      userId: item.userId,
      threadId: item.threadId,
      itemType: 'active-thread' as const,
      title: item.title,
      priority: item.resolutionState === 'unresolved' ? 'high' as const : 'medium' as const,
      sourceTimestamp: item.updatedAt,
    }));

